    27|function parseGithubRepoSlug(value) {
    28|  const normalized = String(value || '').trim();
    29|  if (!normalized) return '';
    30|  if (/^[^/\s]+\/[^/\s]+$/.test(normalized)) return normalized.replace(/\.git$/i, '');
    31|  const match = normalized.match(/github\.com[/:]([^/\s]+)\/([^/.\s]+)(?:\.git)?/i);
    32|  return match ? `${match[1]}/${match[2]}` : '';
    33|}
