    75|function isIgnoredRelativePath(relativePath, opts = {}) {
    76|  const parts = getPathParts(relativePath);
    77|  if (parts.some((part) => IGNORE_DIRS.has(part))) return true;
    78|  // GitHub tokens without the `workflow` scope cannot modify files under .github/workflows.
    79|  // Previously this was unconditionally skipped, which meant CI workflow updates
    80|  // NEVER reached GitHub even when the token had workflow scope.
    81|  // FIX: Only skip if the token explicitly lacks workflow scope (opt-in via env).
