   122|async function githubFetch(path, options = {}) {
   123|  const url = path.startsWith('http') ? path : `${API}${path}`;
   124|  const method = (options.method || 'GET').toUpperCase();
   125|  const res = await fetch(url, {
   126|    ...options,
   127|    headers: {
   128|      Authorization: `Bearer ${GITHUB_TOKEN}`,
   129|      Accept: 'application/vnd.github+json',
   130|      'Content-Type': 'application/json',
   131|      'X-GitHub-Api-Version': '2022-11-28',
   132|      ...options.headers,
   133|    },
   134|  });
   135|
   136|  if (!res.ok && !(res.status === 404 && method === 'GET')) {
   137|    const text = await res.text();
   138|    throw new Error(`GitHub API ${method} ${path} ${res.status} ${res.statusText}: ${text.slice(0, 800)}`);
   139|  }
   140|  if (res.status === 404) return null;
   141|  return res.json();
