   160|async function getRemoteTree(commitSha) {
   161|  const commit = await githubFetch(`/repos/${REPO}/git/commits/${commitSha}`);
   162|  if (!commit) return { treeSha: null, files: new Map() };
   163|
   164|  const tree = await githubFetch(`/repos/${REPO}/git/trees/${commit.tree.sha}?recursive=1`);
   165|  const files = new Map();
   166|  if (tree?.tree) {
   167|    for (const item of tree.tree) {
   168|      if (item.type === 'blob') {
   169|        files.set(item.path, item.sha);
   170|      }
   171|    }
   172|  }
   173|  return { treeSha: commit.tree.sha, files };
